function Write-Tips([string]$dir) {
    if (Test-Path $dir) { Remove-Item $dir -Recurse -Force }
    New-Item -ItemType Directory -Path $dir -Force | Out-Null
    foreach ($tip in $tips) {
        $obj = [ordered]@{
            type       = "tipsmod:simple"
            title      = $tip.t
            text       = $tip.x
            cycle_time = 11000
        }
        $json = ($obj | ConvertTo-Json -Compress -Depth 5)
        [System.IO.File]::WriteAllText((Join-Path $dir ($tip.f + ".json")), $json, $utf8)
    }
    "Wrote $($tips.Count) tips to $dir"
}

Write-Tips $OutDir
Write-Tips $InstanceDir
